insert into public.exercises
  (id, name, muscle_group, equipment, difficulty, duration_min, benefit, impact, tags, unit, easier_ids, how_to)
values
  ('chair-squat', 'Chair squat', 'legs', array['bodyweight']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stand in front of a sturdy chair. Slowly sit down until you lightly touch it, then stand back up. Keep your chest up.'),
  ('bodyweight-squat', 'Bodyweight squat', 'legs', array['bodyweight']::text[], 1, 5, 8, 'low', array['knee_load']::text[], 'reps', array['chair-squat']::text[], 'Feet shoulder-width apart. Push your hips back and bend your knees as if sitting in a chair, then stand up tall.'),
  ('reverse-lunge', 'Reverse lunge', 'legs', array['bodyweight']::text[], 2, 6, 8, 'low', array['knee_load']::text[], 'reps', array['bodyweight-squat']::text[], 'Step one foot back and lower until both knees are bent. Push through the front foot to come back up. Swap legs each time.'),
  ('jump-squat', 'Jump squat', 'legs', array['bodyweight']::text[], 3, 4, 7, 'high', array['knee_load']::text[], 'reps', array['bodyweight-squat']::text[], 'Do a squat, then jump up. Land softly with bent knees and go straight into the next squat.'),
  ('goblet-squat', 'Goblet squat', 'legs', array['dumbbells']::text[], 2, 6, 9, 'low', array['knee_load']::text[], 'reps', array['bodyweight-squat']::text[], 'Hold one dumbbell against your chest with both hands. Squat down keeping your chest tall, then stand up.'),
  ('dumbbell-lunge', 'Dumbbell lunge', 'legs', array['dumbbells']::text[], 3, 7, 9, 'low', array['knee_load']::text[], 'reps', array['reverse-lunge','goblet-squat']::text[], 'Hold a dumbbell in each hand by your sides. Step back into a lunge, then push up. Keep your body upright.'),
  ('band-squat', 'Band squat', 'legs', array['resistance_band']::text[], 2, 5, 7, 'low', array['knee_load']::text[], 'reps', array['bodyweight-squat']::text[], 'Stand on the band with the ends held at your shoulders. Squat down and stand up against the band''s pull.'),
  ('glute-bridge', 'Glute bridge', 'glutes', array['bodyweight']::text[], 1, 4, 7, 'low', '{}'::text[], 'reps', '{}'::text[], 'Lie on your back, knees bent, feet flat. Squeeze your bottom and lift your hips until your body is a straight line. Lower slowly.'),
  ('donkey-kick', 'Donkey kick', 'glutes', array['bodyweight']::text[], 1, 4, 5, 'low', array['wrist_load']::text[], 'reps', '{}'::text[], 'On hands and knees, lift one bent leg up towards the ceiling, squeezing your bottom. Lower and repeat, then switch legs.'),
  ('single-leg-bridge', 'Single-leg bridge', 'glutes', array['bodyweight']::text[], 2, 5, 8, 'low', '{}'::text[], 'reps', array['glute-bridge']::text[], 'Do a glute bridge with one leg held straight in the air. Keep your hips level. Switch legs after each set.'),
  ('dumbbell-glute-bridge', 'Dumbbell glute bridge', 'glutes', array['dumbbells']::text[], 2, 5, 8, 'low', '{}'::text[], 'reps', array['glute-bridge']::text[], 'Do a glute bridge with a dumbbell resting on your hips. Hold it in place with both hands.'),
  ('band-lateral-walk', 'Band lateral walk', 'glutes', array['resistance_band']::text[], 2, 5, 6, 'low', array['knee_load']::text[], 'reps', '{}'::text[], 'Put the band around your thighs. Bend your knees slightly and take small steps to the side, keeping tension on the band.'),
  ('wall-push-up', 'Wall push-up', 'chest', array['bodyweight']::text[], 1, 4, 5, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stand an arm''s length from a wall, hands on it at chest height. Bend your elbows to bring your chest to the wall, then push away.'),
  ('knee-push-up', 'Knee push-up', 'chest', array['bodyweight']::text[], 1, 5, 7, 'low', array['wrist_load']::text[], 'reps', array['wall-push-up']::text[], 'On hands and knees, body straight from head to knees. Lower your chest to the floor, then push back up.'),
  ('push-up', 'Push-up', 'chest', array['bodyweight']::text[], 2, 5, 9, 'low', array['wrist_load']::text[], 'reps', array['knee-push-up']::text[], 'Hands under shoulders, body in a straight line. Lower your chest towards the floor, then press back up.'),
  ('dumbbell-floor-press', 'Dumbbell floor press', 'chest', array['dumbbells']::text[], 2, 6, 8, 'low', '{}'::text[], 'reps', array['knee-push-up']::text[], 'Lie on your back holding a dumbbell in each hand. Press them straight up over your chest, then lower until your elbows touch the floor.'),
  ('band-chest-press', 'Band chest press', 'chest', array['resistance_band']::text[], 2, 5, 6, 'low', '{}'::text[], 'reps', array['knee-push-up']::text[], 'Wrap the band behind your back and hold the ends at chest height. Push your hands forward until your arms are straight, then return slowly.'),
  ('superman', 'Superman hold', 'back', array['bodyweight']::text[], 1, 4, 5, 'low', array['spine_load']::text[], 'seconds', '{}'::text[], 'Lie face down with arms stretched forward. Gently lift your arms and legs a few centimetres and hold. Breathe normally.'),
  ('reverse-snow-angel', 'Reverse snow angel', 'back', array['bodyweight']::text[], 1, 4, 5, 'low', '{}'::text[], 'reps', '{}'::text[], 'Lie face down, arms by your sides. Lift your hands slightly and sweep them in an arc overhead, then back to your sides.'),
  ('band-row', 'Band row', 'back', array['resistance_band']::text[], 1, 5, 7, 'low', '{}'::text[], 'reps', '{}'::text[], 'Sit with legs out, band looped round your feet. Pull the ends towards your belly, squeezing your shoulder blades together.'),
  ('dumbbell-row', 'Dumbbell row', 'back', array['dumbbells']::text[], 2, 6, 9, 'low', array['spine_load']::text[], 'reps', array['band-row']::text[], 'Rest one hand and knee on a chair. Pull a dumbbell up towards your hip, keeping your back flat. Lower slowly, then switch sides.'),
  ('dead-hang', 'Dead hang', 'back', array['pull_up_bar']::text[], 1, 3, 5, 'low', array['overhead']::text[], 'seconds', '{}'::text[], 'Hold a pull-up bar with both hands and hang with straight arms for as long as is comfortable. Keep your shoulders relaxed.'),
  ('negative-pull-up', 'Slow lowering pull-up', 'back', array['pull_up_bar']::text[], 3, 5, 9, 'low', array['overhead']::text[], 'reps', array['dead-hang','band-row']::text[], 'Step up so your chin is over the bar. Lower yourself as slowly as you can until your arms are straight.'),
  ('arm-circles', 'Arm circles', 'shoulders', array['bodyweight']::text[], 1, 3, 4, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stretch your arms out to the sides. Make small circles, then bigger ones. Turn around and repeat the other way.'),
  ('band-lateral-raise', 'Band lateral raise', 'shoulders', array['resistance_band']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', array['arm-circles']::text[], 'Stand on the band, ends in your hands. Lift your arms out to the sides up to shoulder height, then lower slowly.'),
  ('band-face-pull', 'Band face pull', 'shoulders', array['resistance_band']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Hold a band at chest height in front of you. Pull it towards your face, elbows high, then return slowly.'),
  ('dumbbell-lateral-raise', 'Dumbbell lateral raise', 'shoulders', array['dumbbells']::text[], 2, 5, 7, 'low', '{}'::text[], 'reps', array['band-lateral-raise']::text[], 'Hold light dumbbells by your sides. Lift them out to the sides to shoulder height, then lower with control.'),
  ('dumbbell-shoulder-press', 'Dumbbell shoulder press', 'shoulders', array['dumbbells']::text[], 3, 6, 9, 'low', array['overhead']::text[], 'reps', array['dumbbell-lateral-raise']::text[], 'Hold dumbbells at shoulder height. Press them straight up until your arms are straight, then lower slowly.'),
  ('dumbbell-curl', 'Dumbbell bicep curl', 'arms', array['dumbbells']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stand holding dumbbells, palms forward. Bend your elbows to lift the weights to your shoulders, then lower slowly.'),
  ('band-curl', 'Band bicep curl', 'arms', array['resistance_band']::text[], 1, 4, 5, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stand on the band, ends in your hands. Curl your hands up to your shoulders, keeping elbows by your sides.'),
  ('hammer-curl', 'Hammer curl', 'arms', array['dumbbells']::text[], 2, 4, 6, 'low', '{}'::text[], 'reps', array['dumbbell-curl']::text[], 'Hold dumbbells with palms facing each other (like holding a hammer). Curl them up and lower slowly.'),
  ('chair-dip', 'Chair dip', 'arms', array['bodyweight']::text[], 2, 5, 7, 'low', array['wrist_load']::text[], 'reps', '{}'::text[], 'Sit on a sturdy chair edge, hands beside you. Slide forward off the seat and bend your elbows to lower a little, then press up.'),
  ('band-triceps-pushdown', 'Band triceps pushdown', 'arms', array['resistance_band']::text[], 1, 4, 5, 'low', '{}'::text[], 'reps', '{}'::text[], 'Loop the band over a door-top or high hook. Hold the ends and push your hands down until your arms are straight.'),
  ('dead-bug', 'Dead bug', 'core', array['bodyweight']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Lie on your back, arms up, knees bent over hips. Slowly lower the opposite arm and leg, then switch. Keep your lower back flat.'),
  ('knee-plank', 'Knee plank', 'core', array['bodyweight']::text[], 1, 3, 5, 'low', '{}'::text[], 'seconds', '{}'::text[], 'On forearms and knees, body straight from head to knees. Squeeze your tummy and hold.'),
  ('plank', 'Plank', 'core', array['bodyweight']::text[], 2, 3, 8, 'low', '{}'::text[], 'seconds', array['knee-plank']::text[], 'On forearms and toes, body in a straight line. Squeeze your tummy and bottom, and hold while breathing.'),
  ('bird-dog', 'Bird dog', 'core', array['bodyweight']::text[], 1, 4, 6, 'low', array['wrist_load']::text[], 'reps', '{}'::text[], 'On hands and knees, stretch one arm forward and the opposite leg back. Hold a moment, then switch.'),
  ('bicycle-crunch', 'Bicycle crunch', 'core', array['bodyweight']::text[], 2, 4, 7, 'low', '{}'::text[], 'reps', array['dead-bug']::text[], 'Lie on your back. Bring one elbow towards the opposite knee while the other leg straightens, then swap in a slow pedalling motion.'),
  ('mountain-climber', 'Mountain climber', 'core', array['bodyweight']::text[], 3, 4, 7, 'high', array['wrist_load','knee_load']::text[], 'reps', array['plank']::text[], 'Start in a high plank. Drive one knee towards your chest, then quickly switch legs, like running on the spot.'),
  ('band-pallof-press', 'Band Pallof press', 'core', array['resistance_band']::text[], 2, 5, 7, 'low', '{}'::text[], 'reps', array['knee-plank']::text[], 'Fix a band at chest height beside you. Hold it at your chest and press it straight out, resisting the sideways pull. Return slowly.'),
  ('leg-press', 'Leg press machine', 'legs', array['gym']::text[], 1, 6, 8, 'low', array['knee_load']::text[], 'reps', '{}'::text[], 'Sit in the machine with your feet shoulder-width apart on the plate. Push the plate away until your legs are almost straight (do not lock your knees), then bend slowly back.'),
  ('leg-curl-machine', 'Seated leg curl machine', 'legs', array['gym']::text[], 1, 5, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Sit with the pad resting on your lower legs. Pull your heels down and back towards you, then let them return slowly.'),
  ('leg-extension-machine', 'Leg extension machine', 'legs', array['gym']::text[], 1, 5, 5, 'low', array['knee_load']::text[], 'reps', '{}'::text[], 'Sit with the pad on the front of your lower legs. Straighten your legs, pause, then lower slowly. Use a light weight.'),
  ('calf-raise-machine', 'Calf raise machine', 'legs', array['gym']::text[], 1, 4, 4, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stand with the balls of your feet on the platform. Rise up on your toes, pause, then lower your heels slowly.'),
  ('barbell-back-squat', 'Barbell back squat', 'legs', array['gym']::text[], 3, 8, 10, 'low', array['knee_load','spine_load']::text[], 'reps', array['leg-press','goblet-squat']::text[], 'Rest the bar across your upper back. Squat down with your chest up and knees over your toes, then stand. Use a squat rack and ask a gym staff member to check your form first.'),
  ('barbell-hip-thrust', 'Barbell hip thrust', 'glutes', array['gym']::text[], 2, 6, 9, 'low', '{}'::text[], 'reps', array['dumbbell-glute-bridge']::text[], 'Sit with your upper back against a bench and a padded bar across your hips. Drive your hips up until your body is straight from shoulders to knees, then lower.'),
  ('cable-kickback', 'Cable glute kickback', 'glutes', array['gym']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Clip the ankle strap to a low cable. Keeping your knee slightly bent, push your leg straight back, squeeze, and return slowly. Do all reps on one leg, then switch.'),
  ('hip-abduction-machine', 'Hip abduction machine', 'glutes', array['gym']::text[], 1, 4, 5, 'low', '{}'::text[], 'reps', '{}'::text[], 'Sit with the pads on the outside of your knees. Push your legs apart, pause, and bring them back slowly.'),
  ('machine-chest-press', 'Machine chest press', 'chest', array['gym']::text[], 1, 5, 7, 'low', '{}'::text[], 'reps', '{}'::text[], 'Sit with the handles at chest height and your back flat against the pad. Push forward until your arms are almost straight, then return slowly.'),
  ('pec-deck-fly', 'Pec deck fly', 'chest', array['gym']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Sit with your arms on the pads. Bring your arms together in front of your chest, squeeze, and open slowly.'),
  ('cable-fly', 'Cable chest fly', 'chest', array['gym']::text[], 2, 5, 7, 'low', '{}'::text[], 'reps', array['pec-deck-fly']::text[], 'Stand between two cables set at chest height. With a slight bend in your elbows, bring your hands together in front of you, then open slowly.'),
  ('barbell-bench-press', 'Barbell bench press', 'chest', array['gym']::text[], 3, 7, 10, 'low', array['wrist_load']::text[], 'reps', array['machine-chest-press','dumbbell-floor-press']::text[], 'Lie on a bench with your feet on the floor. Lower the bar to your chest, then press it up. Always use a spotter or the safety bars.'),
  ('lat-pulldown', 'Lat pulldown', 'back', array['gym']::text[], 1, 5, 8, 'low', array['overhead']::text[], 'reps', '{}'::text[], 'Sit with your thighs under the pad. Pull the bar down to your upper chest, squeezing your shoulder blades, then let it rise slowly.'),
  ('seated-cable-row', 'Seated cable row', 'back', array['gym']::text[], 1, 5, 8, 'low', '{}'::text[], 'reps', '{}'::text[], 'Sit tall with your feet on the plates. Pull the handle to your belly, keeping your back straight, then return slowly.'),
  ('machine-row', 'Chest-supported machine row', 'back', array['gym']::text[], 1, 5, 7, 'low', '{}'::text[], 'reps', '{}'::text[], 'Rest your chest on the pad and hold the handles. Pull your elbows back, squeeze, and return slowly.'),
  ('assisted-pull-up-machine', 'Assisted pull-up machine', 'back', array['gym']::text[], 2, 5, 8, 'low', array['overhead']::text[], 'reps', array['lat-pulldown']::text[], 'Kneel on the pad, which helps lift you. Pull yourself up until your chin is over the bar, then lower slowly.'),
  ('machine-shoulder-press', 'Machine shoulder press', 'shoulders', array['gym']::text[], 1, 5, 8, 'low', array['overhead']::text[], 'reps', '{}'::text[], 'Sit with your back against the pad and the handles at shoulder height. Press up until your arms are almost straight, then lower slowly.'),
  ('cable-lateral-raise', 'Cable lateral raise', 'shoulders', array['gym']::text[], 2, 4, 6, 'low', '{}'::text[], 'reps', array['dumbbell-lateral-raise']::text[], 'Stand side-on to a low cable. Lift your arm out to the side to shoulder height, then lower slowly.'),
  ('reverse-pec-deck', 'Reverse pec deck', 'shoulders', array['gym']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Sit facing the pad, arms out in front. Open your arms out to the sides, squeezing your shoulder blades, then return slowly.'),
  ('cable-triceps-pushdown', 'Cable triceps pushdown', 'arms', array['gym']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stand at a high cable holding the bar. Keep your elbows by your sides and push down until your arms are straight, then let it rise slowly.'),
  ('cable-biceps-curl', 'Cable biceps curl', 'arms', array['gym']::text[], 1, 4, 6, 'low', '{}'::text[], 'reps', '{}'::text[], 'Stand facing a low cable. Curl the handle up to your shoulders, keeping your elbows still, then lower slowly.'),
  ('preacher-curl-machine', 'Preacher curl machine', 'arms', array['gym']::text[], 1, 4, 5, 'low', '{}'::text[], 'reps', '{}'::text[], 'Rest your upper arms on the pad. Curl the handles up, then lower slowly until your arms are almost straight.'),
  ('cable-crunch', 'Cable crunch', 'core', array['gym']::text[], 2, 4, 7, 'low', array['spine_load']::text[], 'reps', array['dead-bug']::text[], 'Kneel below a high cable holding the rope at your head. Curl your chest towards your knees, then return slowly.'),
  ('cable-woodchop', 'Cable woodchop', 'core', array['gym']::text[], 2, 4, 7, 'low', '{}'::text[], 'reps', array['band-pallof-press']::text[], 'Stand side-on to a high cable. Pull the handle down and across your body, turning your trunk, then return slowly. Switch sides.'),
  ('hanging-leg-raise', 'Hanging leg raise', 'core', array['gym']::text[], 3, 4, 8, 'low', array['overhead']::text[], 'reps', array['bicycle-crunch']::text[], 'Hang from a bar or use the captain''s chair. Raise your bent knees towards your chest, then lower slowly without swinging.')
